const fs = require('node:fs'), cp = require('node:child_process'), assert = require('node:assert/strict');
const {chromium} = require('<PLAYWRIGHT_MODULE>');
const root = '<EASYSTUD_SOURCE_ROOT>';
const runId = 'codex1-k1680-tail-f25p-native', out = __dirname;
const ps = (file, args) => cp.execFileSync('powershell.exe', ['-NoProfile', '-File', '<ORCHESTRATION_SCRIPTS>/' + file, ...args], {encoding: 'utf8'});
const css = file => fs.readFileSync(file, 'utf8').replace(/url\((["']?)(\.\.?\/[^)"']+)\1\)/g,
    (match, quote, relative) => 'url("' + new URL(relative, 'http://localhost:8051/local/groupimport/styles/student-management.css').href + '")');
async function settle(locator) {
    await locator.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(()=>requestAnimationFrame(r)))));
    await locator.evaluate(async node => {
        const animations = [...node.getAnimations({subtree:true})];
        for (let n = node; n; n = n.parentElement) animations.push(...n.getAnimations());
        await Promise.all(animations.filter(a => Number.isFinite(a.effect.getTiming().iterations)).map(a => a.finished.catch(() => {})));
    });
}
async function measure(locator){return locator.evaluate(node=>{
 const m=n=>{const r=n.getBoundingClientRect(),s=getComputedStyle(n);return {width:r.width,height:r.height,padding:s.padding,radius:s.borderRadius,color:s.color,background:s.backgroundColor,border:s.border,fontSize:s.fontSize,lineHeight:s.lineHeight};};
 const buttons=[...(node.matches('button')?[node]:node.querySelectorAll(node.matches('[data-easystud-group-email-panel]')?'button':'.local-groupimport-easystud-tags-toggle'))].filter(n=>n.getClientRects().length).map(n=>{
  const h=n.getBoundingClientRect(),walker=document.createTreeWalker(n,NodeFilter.SHOW_TEXT),rects=[];while(walker.nextNode()){if(!walker.currentNode.textContent.trim())continue;const range=document.createRange();range.selectNodeContents(walker.currentNode);rects.push(...range.getClientRects());}
  for(const icon of n.querySelectorAll('.fa')){const text=document.createTextNode(getComputedStyle(icon,'::before').content.slice(1,-1));icon.classList.add('codex1-range-probe');icon.append(text);const range=document.createRange();range.selectNodeContents(text);rects.push(range.getBoundingClientRect());text.remove();icon.classList.remove('codex1-range-probe');}
  if(!rects.length)throw Error('No painted control content');return {...m(n),x:(Math.min(...rects.map(r=>r.x))+Math.max(...rects.map(r=>r.right)))/2-h.x-h.width/2,y:(Math.min(...rects.map(r=>r.y))+Math.max(...rects.map(r=>r.bottom)))/2-h.y-h.height/2};
 });
 return {frame:m(node),buttons,parts:[...node.querySelectorAll('textarea,[data-easystud-group-email-result],.local-groupimport-easystud-token')].filter(n=>n.getClientRects().length).map(m)};
 });}

(async () => {
    const result = {passed: false, rows: [], errors: [], runtimeFilesChanged: false};
    let lease = false, created = false, browser, page;
    try {
        ps('Acquire-EasyEduResourceLease.ps1', ['-Resource', 'moodle51-perf', '-ProjectNamespace', 'easystud', '-RunId', runId,
            '-Repository', root, '-Purpose', 'K16-80 disclosures exact native CSS parity, restored synthetic fixture', '-LeaseSeconds', '900', '-OwnerPid', String(process.pid)]);
        lease = true;
        const fixture = JSON.parse(cp.execFileSync('<PHP_BINARY>', [out + '/fixture.php', 'create'], {encoding: 'utf8'}));
        created = true; result.course = fixture.courseid;
        browser = await chromium.launch({headless: true, executablePath: '<CHROME_EXECUTABLE>'});
        for (const locale of ['fr', 'en']) for (const width of [1600, 390]) {
            const context = await browser.newContext({storageState: '<PROCESS_LOCAL_AUTH_STATE>',
                viewport: {width, height: 1000}, hasTouch: width === 390, reducedMotion: 'reduce'});
            page = await context.newPage();
            page.setDefaultTimeout(20000);
            page.on('pageerror', e => result.errors.push(e.message));
            page.on('console', m => {if (m.type() === 'error') result.errors.push(m.text());});
            const response = await page.goto('http://localhost:8051/local/groupimport/manage.php?id=' + fixture.courseid + '&lang=' + locale,
                {waitUntil: 'domcontentloaded', timeout: 180000});
            assert.equal(response.status(), 200);
            await page.waitForFunction(() => {
                const r = document.querySelector('#local-groupimport-easystud');
                return r?.dataset.easystudManagerInitialised === '1' && !r.classList.contains('is-action-busy') && !r.classList.contains('local-groupimport-easystud--booting');
            }, null, {timeout: 180000});
            const both = page.locator('[data-easystud-layout-mode="both"]'); if (await both.isVisible()) await both.click();
            if (width < 1024) await page.locator('[data-easystud-mobile-view="groups"]').click();
            await page.evaluate(() => {
                document.querySelectorAll('link[rel="stylesheet"]').forEach(n => {if (/\/local\/groupimport\/styles\//.test(n.href)) n.disabled = true;});
            });
            const style = await page.addStyleTag({content: css(out + '/before-student-management.css')});
            await page.addStyleTag({content: '.codex1-range-probe::before {content:none!important;}'});
            await page.evaluate(() => document.fonts.ready);
            async function capture(kind,target){await target.waitFor();for(const phase of ['before','after']){await style.evaluate((n,t)=>{n.textContent=t;},css(phase==='before'?out+'/before-student-management.css':root+'/styles/student-management.css'));await settle(target);result.rows.push({kind,locale,width,phase,measurement:await measure(target)});}}
            if(width<1024)await page.locator('[data-easystud-mobile-view="groups"]').click();
            const unassigned=page.locator('[aria-controls="easystud-group-list-ungrouped"]');if(await unassigned.isVisible()&&await unassigned.getAttribute('aria-expanded')==='false')await unassigned.click();
            const card=page.locator('[data-selectable-type="group"]:visible').filter({has:page.locator('[data-easystud-grouping-summary-toggle]')}).first();if(!await card.isVisible()){if(width<1024)await page.locator('[data-easystud-mobile-view="groupings"]').click();const toggle=page.locator('[data-selectable-type="grouping"]:visible').first().locator('[data-easystud-collapse-toggle]').first();if(await toggle.getAttribute('aria-expanded')==='false')await toggle.click();}result.hostDiagnostics??=[];result.hostDiagnostics.push({locale,width,visibleGroups:await page.locator('[data-selectable-type="group"]:visible').count(),summaryButtons:await page.locator('[data-easystud-grouping-summary-toggle]').count()});await card.waitFor();
            const summary=card.locator('[data-easystud-grouping-summary-toggle]');if(await summary.isVisible())await capture('membership-summary',summary);else{assert.equal(width,390,'Summary must paint at desktop');for(const phase of ['before','after']){await style.evaluate((n,t)=>{n.textContent=t;},css(phase==='before'?out+'/before-student-management.css':root+'/styles/student-management.css'));await settle(card);const rect=await card.boundingBox();result.rows.push({kind:'membership-summary',locale,width,phase,measurement:{notRendered:true,buttons:[],cardWidth:rect.width,cardHeight:rect.height}});}}
            if(width<1024)await page.locator('[data-easystud-mobile-view="participants"]').click();
            const person=page.locator('[data-selectable-type="participant"]:visible').first();await person.waitFor();const density=page.locator(width<1024?'[data-easystud-mobile-membership-toggle]:visible':'[data-easystud-density-toggle]:visible').first();if(await density.getAttribute('aria-pressed')==='true')await density.click();await person.locator('.local-groupimport-easystud-tags-toggle:visible').first().waitFor();assert.ok(await person.locator('.local-groupimport-easystud-tags-toggle:visible').count()>0,'Actual full-info membership overflow shown through its native density command');await capture('metadata-overflow',person);
            await context.close();
        }
        assert.equal(result.rows.length,16);for(const a of result.rows.filter(r=>r.phase==='after')){const before=result.rows.find(r=>r.phase==='before'&&r.kind===a.kind&&r.locale===a.locale&&r.width===a.width);assert.deepEqual(a.measurement,before.measurement,'All actual widget dimensions, insets, paint and content centres unchanged');assert.ok(a.measurement.notRendered||a.measurement.buttons.length);for(const c of a.measurement.buttons)assert.ok(Math.abs(c.x)<=0.5&&Math.abs(c.y)<=0.5,'Adopted summary/token control Range centre within0.5px');}
        for(const locale of ['fr','en'])assert.ok(result.rows.some(r=>r.locale===locale&&r.width===1600&&r.kind==='membership-summary'&&r.measurement.buttons.length),'Actual desktop summary paint required');
        result.excludedInlineEntry={status:'not-adopted',evidence:'unvalidated-inline-entry-native.json',reason:'Existing non-centred and unequal mobile controls need a separate visual decision'};
        assert.equal(result.errors.length, 0); result.passed = true;
    } catch (e) {
        result.failure = e.message;
        if (page && !page.isClosed()) await page.screenshot({path: out + '/failure.png', timeout: 10000}).catch(() => {});
    } finally {
        if (browser) await browser.close();
        if (!created && fs.existsSync(out + '/fixture-ids.json')) {
            const ids = JSON.parse(fs.readFileSync(out + '/fixture-ids.json'));
            const restored = fs.existsSync(out + '/fixture-restored.json') ? JSON.parse(fs.readFileSync(out + '/fixture-restored.json')) : {};
            created = !(restored.removed && restored.courseid === ids.courseid);
        }
        if (created) result.fixtureCleanup = JSON.parse(cp.execFileSync('<PHP_BINARY>', [out + '/fixture.php', 'cleanup'], {encoding: 'utf8'}));
        if (lease) {ps('Release-EasyEduResourceLease.ps1', ['-Resource', 'moodle51-perf', '-RunId', runId]); result.leaseReleased = true;}
        fs.writeFileSync(out + '/native.json', JSON.stringify(result, null, 2));
        console.log(JSON.stringify({passed: result.passed, rows: result.rows.length, errors: result.errors.length, failure: result.failure, restored: result.fixtureCleanup, leaseReleased: result.leaseReleased}));
    }
})();
